import collections
import datetime as dt
import hashlib
import json
import pathlib
import re
import sqlite3
import zipfile
from urllib.parse import quote

BASE = pathlib.Path(r'C:\Users\User\.codex')
OUT = pathlib.Path(__file__).parent / 'Codex-arhive-2026-10-07'
OUT.mkdir(exist_ok=True)
STAMP = dt.datetime.now(dt.timezone.utc).isoformat()

def read_db(name):
    source = sqlite3.connect((BASE / name).as_uri() + '?mode=ro', uri=True)
    dest = sqlite3.connect(':memory:')
    source.backup(dest)
    source.close()
    dest.row_factory = sqlite3.Row
    return dest

state = read_db('state_5.sqlite')
history = read_db('thread_history_1.sqlite')
settings = json.loads((BASE / '.codex-global-state.json').read_text(encoding='utf-8'))
projects = {k: v for k, v in settings['local-projects'].items() if not k.startswith('g-p-')}
assignments = settings.get('thread-project-assignments', {})
new_to_old = {}
for mapping in settings.get('app-server-project-id-by-legacy-project-id-by-host', {}).values():
    new_to_old.update({v: k for k, v in mapping.items()})
threads = {r['id']: dict(r) for r in state.execute('SELECT * FROM threads')}
parents = {r['child_thread_id']: r['parent_thread_id'] for r in state.execute('SELECT * FROM thread_spawn_edges')}
for tid, row in threads.items():
    try:
        parent = json.loads(row['source']).get('subagent', {}).get('thread_spawn', {}).get('parent_thread_id')
        if parent:
            parents[tid] = parent
    except (ValueError, AttributeError):
        pass

def norm(path):
    path = path.replace('/', '\\')
    if path.lower().startswith('\\\\?\\unc\\'):
        path = '\\\\' + path[8:]
    elif path.startswith('\\\\?\\'):
        path = path[4:]
    aliases = {'z:': r'\\192.168.100.169\Comun', 's:': r'\\192.168.100.151\site-uri'}
    if path[:2].lower() in aliases:
        path = aliases[path[:2].lower()] + path[2:]
    return path.rstrip('\\').casefold()

def resolve_project(tid, visited=None):
    visited = set() if visited is None else visited
    if tid in visited or tid not in threads:
        return None, 'unresolved'
    visited.add(tid)
    row = threads[tid]
    pid = assignments.get(tid, {}).get('projectId')
    if pid in projects:
        return pid, 'app_assignment'
    pid = new_to_old.get(row.get('project_id'), row.get('project_id'))
    if pid in projects:
        return pid, 'database_assignment'
    if tid in parents:
        pid, _ = resolve_project(parents[tid], visited)
        if pid:
            return pid, 'parent_thread'
    if tid in settings.get('projectless-thread-ids', []):
        return None, 'explicitly_projectless'
    cwd = norm(row['cwd'])
    matches = []
    for pid, p in projects.items():
        for root in p['rootPaths']:
            root = norm(root)
            if cwd == root or cwd.startswith(root + '\\'):
                matches.append((len(root), pid))
    if matches:
        return max(matches)[1], 'workspace_path'
    return None, 'unassigned'

def safe(text):
    return re.sub(r'[<>:"/\\|?*\x00-\x1f]', '_', text).strip(' .')[:90] or 'Fara titlu'

def write_json(path, data):
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')

def text_content(item):
    if item.get('type') == 'agentMessage':
        return item.get('text', '')
    chunks = []
    for part in item.get('content', []):
        if isinstance(part, str):
            chunks.append(part)
        elif part.get('text') is not None:
            chunks.append(part['text'])
        else:
            chunks.append('[Atașament / conținut non-text: ' + json.dumps(part, ensure_ascii=False) + ']')
    return '\n\n'.join(chunks)

EXCLUDED_TYPES = {'reasoning', 'contextCompaction'}
def visible(item):
    return item.get('type') not in EXCLUDED_TYPES and item.get('phase') not in {'analysis', 'justify', 'confidence'}

def load_items(row):
    items = collections.OrderedDict()
    legacy = []
    invalid = 0
    path = pathlib.Path(row['rollout_path'])
    file_size = path.stat().st_size if path.exists() else 0
    if file_size:
        with path.open('rb') as stream:
            data = stream.read(file_size)
        for ordinal, line in enumerate(data.splitlines()):
            try:
                record = json.loads(line)
            except (ValueError, UnicodeDecodeError):
                invalid += 1
                continue
            p = record.get('payload', {})
            if record.get('type') == 'event_msg' and p.get('type') == 'item_completed':
                item = p.get('item', {})
                if visible(item):
                    key = item.get('id') or str(ordinal)
                    items[key] = {'ordinal': ordinal, 'timestamp': record.get('timestamp'), 'turn_id': p.get('turn_id'), 'item': item}
            elif record.get('type') == 'event_msg' and p.get('type') in {'user_message', 'agent_message'}:
                kind = 'userMessage' if p['type'] == 'user_message' else 'agentMessage'
                item = {'type': kind, 'id': 'legacy-' + str(ordinal)}
                if kind == 'userMessage':
                    item['content'] = [{'type': 'text', 'text': p.get('message', '')}]
                    for attachment in p.get('images', []) + p.get('local_images', []):
                        item['content'].append({'type': 'attachmentReference', 'reference': attachment})
                else:
                    item.update(text=p.get('message', ''), phase=p.get('phase'))
                if visible(item):
                    legacy.append({'ordinal': ordinal, 'timestamp': record.get('timestamp'), 'item': item})
    for r in history.execute('SELECT * FROM thread_items WHERE thread_id=? ORDER BY rollout_ordinal', (row['id'],)):
        item = json.loads(r['item_json'])
        if visible(item) and r['item_id'] not in items:
            items[r['item_id']] = {'ordinal': r['rollout_ordinal'], 'created_at_ms': r['created_at_ms'], 'turn_id': r['turn_id'], 'item': item}
    result = sorted(items.values(), key=lambda x: x['ordinal']) if items else legacy
    return result, {'source_bytes': file_size, 'invalid_json_lines': invalid, 'history_source': 'items' if items else 'legacy_events', 'rollout_exists': path.exists()}

manifest = {'format_version': 1, 'export_started_at_utc': STAMP, 'repository': 'https://github.com/covaciugnm/Codex', 'upload_status': 'pending_visibility_confirmation', 'projects': [], 'threads': [], 'excluded_internal_sessions': [], 'limitations': ['Export local Codex; conversațiile ChatGPT din cloud nu sunt incluse.', 'Mesajele și evenimentele sunt păstrate în JSON; fișierele externe indicate în mesaje nu sunt copiate.', 'Instrucțiunile interne și raționamentul intern nu sunt exportate.', 'Conversațiile în desfășurare sunt capturate până la momentul citirii.', 'Asocierile deduse din director sunt marcate separat de asocierile explicite.']}
groups = collections.defaultdict(list)
for tid, row in threads.items():
    if 'guardian' in row['source']:
        manifest['excluded_internal_sessions'].append(tid)
        continue
    pid, method = resolve_project(tid)
    groups[pid].append((row, method))

for pid, project in list(projects.items()) + [(None, {'name': '_Fara proiect', 'rootPaths': []})]:
    folder = OUT / safe(project['name'])
    folder.mkdir(exist_ok=True)
    entries = []
    for row, method in sorted(groups[pid], key=lambda pair: (pair[0]['created_at'], pair[0]['id'])):
        items, diagnostics = load_items(row)
        is_subagent = row['id'] in parents or 'subagent' in row['source']
        subdir = folder / ('subagenti' if is_subagent else 'conversatii')
        subdir.mkdir(exist_ok=True)
        stem = row['id']
        title = row.get('name') or row['title'] or 'Fara titlu'
        metadata = {k: row[k] for k in ['id', 'cwd', 'created_at', 'updated_at', 'archived', 'source']}
        metadata.update(title=title, project_id=pid, project=project['name'], assignment_method=method, parent_thread_id=parents.get(row['id']), export_started_at_utc=STAMP, **diagnostics)
        messages = [x for x in items if x['item'].get('type') in {'userMessage', 'agentMessage'}]
        metadata.update(item_count=len(items), message_count=len(messages))
        write_json(subdir / (stem + '.json'), {'metadata': metadata, 'items': items})
        parts = [f'# {title}', f"ID: `{row['id']}`  \nProiect: {project['name']}  \nExport: {STAMP}", 'Mesajele text sunt redate mai jos; evenimentele instrumentelor și datele structurate se găsesc în fișierul JSON alăturat.']
        for event in messages:
            item = event['item']
            label = 'Utilizator' if item['type'] == 'userMessage' else 'Asistent'
            parts.extend([f'## {label}', text_content(item)])
        if not messages:
            parts.append('Nu există mesaje conversaționale în istoricul local al acestei sesiuni.')
        (subdir / (stem + '.md')).write_text('\n\n'.join(parts) + '\n', encoding='utf-8')
        entry = {**metadata, 'subagent': is_subagent, 'markdown': (subdir / (stem + '.md')).relative_to(OUT).as_posix(), 'json': (subdir / (stem + '.json')).relative_to(OUT).as_posix()}
        entries.append(entry)
        manifest['threads'].append(entry)
    project_info = {'id': pid, 'name': project['name'], 'roots': project['rootPaths'], 'conversations': sum(not e['subagent'] for e in entries), 'subagents': sum(e['subagent'] for e in entries), 'messages': sum(e['message_count'] for e in entries)}
    write_json(folder / 'index.json', {'project': project_info, 'threads': entries})
    lines = [f"# {project['name']}", f"Conversații: {project_info['conversations']}; subagenți: {project_info['subagents']}; mesaje: {project_info['messages']}.", '| Conversație | Tip | Mesaje |', '|---|---|---|']
    for e in entries:
        title = e['title'].replace('\n', ' ').replace('|', '\\|')[:180]
        relative = pathlib.PurePosixPath(e['markdown']).relative_to(folder.name).as_posix()
        lines.append(f"| [{title}]({quote(relative)}) | {'Subagent' if e['subagent'] else 'Conversație'} | {e['message_count']} |")
    if not entries:
        lines.append('\nNicio conversație locală asociată acestui proiect la momentul exportului.')
    (folder / 'README.md').write_text('\n\n'.join(lines[:2]) + '\n\n' + '\n'.join(lines[2:]) + '\n', encoding='utf-8')
    zip_path = folder / 'conversatii.zip'
    with zipfile.ZipFile(zip_path, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
        for path in sorted(folder.rglob('*')):
            if path.is_file() and path != zip_path:
                archive.write(path, path.relative_to(folder).as_posix())
    with zipfile.ZipFile(zip_path) as archive:
        assert archive.testzip() is None
    project_info.update(zip=zip_path.relative_to(OUT).as_posix(), zip_bytes=zip_path.stat().st_size, zip_sha256=hashlib.sha256(zip_path.read_bytes()).hexdigest())
    manifest['projects'].append(project_info)
    print(json.dumps(project_info, ensure_ascii=True), flush=True)

manifest['totals'] = {'projects': len(projects), 'conversations': sum(not t['subagent'] for t in manifest['threads']), 'subagents': sum(t['subagent'] for t in manifest['threads']), 'messages': sum(t['message_count'] for t in manifest['threads']), 'internal_sessions_excluded': len(manifest['excluded_internal_sessions']), 'missing_rollouts': sum(not t['rollout_exists'] for t in manifest['threads']), 'invalid_json_lines': sum(t['invalid_json_lines'] for t in manifest['threads'])}
write_json(OUT / 'manifest.json', manifest)
root_lines = ['# Arhive conversații Codex', 'Export din 7 octombrie 2026, organizat după proiectele locale Codex.', f"{manifest['totals']['conversations']} conversații principale și {manifest['totals']['subagents']} sesiuni de subagenți; {manifest['totals']['messages']} mesaje.", 'Fiecare proiect are un index, transcrieri Markdown, evenimente JSON și arhiva conversatii.zip. Directorul _Fara proiect păstrează separat sesiunile fără asociere. Exportul nu modifică și nu arhivează conversațiile în aplicație.', 'Încărcare GitHub: în așteptarea confirmării privind vizibilitatea depozitului public.', '| Proiect | Conversații | Subagenți | Arhivă |', '|---|---:|---:|---|']
for p in manifest['projects']:
    root_lines.append(f"| [{p['name']}]({quote(safe(p['name']))}/README.md) | {p['conversations']} | {p['subagents']} | [ZIP]({quote(p['zip'])}) |")
root_lines.extend(['', '## Acoperire și limite', ''] + ['- ' + x for x in manifest['limitations']])
(OUT / 'README.md').write_text('\n\n'.join(root_lines[:5]) + '\n\n' + '\n'.join(root_lines[5:]) + '\n', encoding='utf-8')
checksums = []
for path in sorted(OUT.rglob('*')):
    if path.is_file() and path.name != 'SHA256SUMS.txt':
        checksums.append(hashlib.sha256(path.read_bytes()).hexdigest() + '  ' + path.relative_to(OUT).as_posix())
(OUT / 'SHA256SUMS.txt').write_text('\n'.join(checksums) + '\n', encoding='utf-8')
print('TOTALS', json.dumps(manifest['totals']))
print('OUTPUT', str(OUT))

